"""Summarize a verified frozen final challenge without changing its selection."""
from fractions import Fraction
from pathlib import Path
from datetime import datetime,timezone
import argparse,json,math,os
import numpy as np
from blotto_lab.core import validate_allocation
from game2_lab.core import focal_samples,reference_group
from game2_lab.weights import cubic_value
from run_population_study import ROOT,save,sha,write_csv
from verify_population_study import rational


def read(p):return json.loads(p.read_text())


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--study',type=Path,default=ROOT/'results/game2-final');parser.add_argument('--output',type=Path,default=ROOT/'results/game2-selection-review');parser.add_argument('--report',type=Path,default=ROOT.parent/'23-game2-final-selection.md');args=parser.parse_args();study=args.study.resolve();out=args.output.resolve();report=args.report.resolve()
    if out.exists():raise SystemExit('Output exists. Use a new review folder.')
    r=read(study/'results.json');a=read(study/'acceptance.json');assert a['passed']and a['freeze_sha256']==r['freeze_sha256']and a['recommendation']==r['selected_allocation']
    cfg=r['configuration'];p=r['policy'];selected=p['selected_candidate_id'];allocation=validate_allocation(r['selected_allocation']);N=cfg['evaluation_triplets'];candidates=r['candidates'];out.mkdir(parents=True)
    weights={g:{k:rational(v)for k,v in w.items()}for g,w in p['block_weights'].items()};regret_intervals={}
    for cid in candidates:
        gaps={g:rational(v)for g,v in p['block_regrets'][cid].items()};lo=max(0,max(float(v)-2*r['block_error_bounds'][g]for g,v in gaps.items()));hi=max(float(v)+2*r['block_error_bounds'][g]for g,v in gaps.items());regret_intervals[cid]={'lower':lo,'upper':hi}
    excess=max(0,regret_intervals[selected]['upper']-min(v['lower']for v in regret_intervals.values()))
    retained={selected,*p['alternatives'].values(),r['comparison_tags']['human_100'],r['comparison_tags']['combined_cap_0.25']};profile_ids=sorted(retained);profiles={cid:{}for cid in profile_ids};raw={cid:{}for cid in profile_ids}
    for key in r['cell_keys']:
        with np.load(study/'evaluation'/(key+'.npz'))as f:rows=f['triplets']
        for cid in profile_ids:
            x=candidates[cid]['allocation'];samples=focal_samples(x,rows);maximum=rows.max(axis=1);ties=(rows==maximum[:,None,:]).sum(axis=1);gt=np.array(x)>maximum;eq=np.array(x)==maximum
            raw[cid][key]={'payout4':int(samples['payout4'].sum()),'castle12':int(samples['castle12'].sum()),'finish12':samples['finish_credits12'].sum(axis=0).tolist(),'castle_credit12':(12*gt+eq*(12//(ties+1))).sum(axis=0).tolist(),'outright_first':int(samples['outright_first'].sum()),'rank_tie':int(samples['rank_tie'].sum())}
    for cid in profile_ids:
        for group,w in weights.items():
            score=sum(mass*Fraction(raw[cid][key]['payout4'],4*N)for key,mass in w.items());assert score==rational(p['block_scores'][cid][group]);castle=sum(mass*Fraction(raw[cid][key]['castle12'],12*N)for key,mass in w.items())
            finish=[sum(mass*Fraction(int(raw[cid][key]['finish12'][j]),12*N)for key,mass in w.items())for j in range(4)];credits=[sum(mass*Fraction(int(raw[cid][key]['castle_credit12'][j]),12*N)for key,mass in w.items())for j in range(5)]
            assert sum(finish)==1 and sum(v*z for v,z in zip([9,4,2,0],finish))==score and sum(v*z for v,z in zip(range(1,6),credits))==castle
            profiles[cid][group]={'ranking_payout':score,'castle_points':castle,'finish_credits':finish,'castle_credit_fractions':credits,'outright_first_probability':sum(mass*Fraction(raw[cid][key]['outright_first'],N)for key,mass in w.items()),'rank_tie_probability':sum(mass*Fraction(raw[cid][key]['rank_tie'],N)for key,mass in w.items())}
    counter=r['homogeneous_stress'][selected]['exact_worst_clone'];group=reference_group([allocation]+[counter['opponent']]*3);assert group.payouts[0]==rational(counter['payout'])
    result={'created_utc':datetime.now(timezone.utc).isoformat(),'selected_candidate_id':selected,'recommendation':allocation,'game1_recommendation':cfg['game1_recommendation'],'selection_rule':cfg['selection_rule'],
        'regret_intervals':regret_intervals,'selected_regret_interval':regret_intervals[selected],'selected_excess_regret_bound_within_frozen_field':excess,'profile':profiles,'exact_counter':counter,'counter_group':group,
        'alternatives':{name:candidates[cid]['allocation']for name,cid in p['alternatives'].items()},'freeze_sha256':r['freeze_sha256'],'input_sha256':{os.path.relpath(f,ROOT):sha(f)for f in [study/'results.json',study/'acceptance.json',study/'candidate-freeze.json']},
        'official_rules_check':{'date':'2026-10-30','url':'https://pokerbot.sequoiacap.com/','game2_prizes':[9,4,2,0],'castle_and_ranking_ties':'Shared as in the simulator','pittsburgh_event':'2026-11-12','pittsburgh_application_deadline':'2026-11-09 23:59 America/New_York'},
        'status':'Recommended, not submitted','scope':'A fixed decision under the frozen coverage policy, not a universal optimum or applicant forecast'}
    save(out/'results.json',result);(out/'selected-game2.txt').write_text(' '.join(map(str,allocation))+'\n');(out/'submission-vectors.txt').write_text('Game 1: '+' '.join(map(str,cfg['game1_recommendation']))+'\nGame 2: '+' '.join(map(str,allocation))+'\n')
    comparison=[selected,p['alternatives']['lowest_model_score'],p['ranking'][1],r['comparison_tags']['human_100'],r['comparison_tags']['human_96'],r['comparison_tags']['human_89'],r['comparison_tags']['combined_cap_0.25'],r['comparison_tags']['family_cap_0.25'],r['comparison_tags']['rank_tail_mean'],r['comparison_tags']['rank_tail_minimum'],r['comparison_tags']['fort_4']];comparison=list(dict.fromkeys(comparison))
    write_csv(out/'primary-comparison.csv',['rank','allocation','core_mean','pressure_mean','arena_mean','equal_block_mean','largest_block_regret','lowest_primary_model_score'],[[p['ranking'].index(cid)+1,str(tuple(candidates[cid]['allocation'])),*[float(rational(p['block_scores'][cid][g]))for g in ['core','pressure','arenas']],float(rational(p['equal_block_mean'][cid])),float(rational(p['maximum_block_regret'][cid])),float(rational(p['lowest_model_score'][cid]))]for cid in comparison])
    # Full prevalence curves are derived from the frozen conditional cells, with no new fits.
    cids=list(candidates);cell_keys=r['cell_keys']
    with np.load(study/'evaluation-sums.npz')as f:values=f['rank_sum4']/(4*N)
    curve_ids=list(dict.fromkeys(comparison+[p['alternatives']['low_copy_core_mean']]));curves=[]
    for cid in curve_ids:
        j=cids.index(cid)
        for ref,ids in r['design']['core_references'].items():
            coeff=values[j,[cell_keys.index(key)for key in ids]]
            for percent in range(101):curves.append([cid,str(tuple(candidates[cid]['allocation'])),ref,percent/100,float(cubic_value(coeff,percent/100))])
    write_csv(out/'copy-curves.csv',['candidate_id','allocation','reference','copy_share','payout'],curves)
    # User-facing findings. All performance quantities remain conditional model scores.
    f=lambda x:f'{float(rational(x)):.3f}';sel=p['selected_candidate_id'];alt=p['alternatives']['lowest_model_score'];near=p['ranking'][1]
    label={sel:'Recommendation',alt:'Best lowest-model score',near:'Nearest regret competitor',r['comparison_tags']['human_100']:'Your all-in five',r['comparison_tags']['human_96']:'Your 96-five',r['comparison_tags']['human_89']:'Your 89-five',r['comparison_tags']['combined_cap_0.25']:'Previous compromise',r['comparison_tags']['family_cap_0.25']:'Previous family-only choice',r['comparison_tags']['rank_tail_mean']:'Previous arena-average choice',r['comparison_tags']['rank_tail_minimum']:'Previous arena-minimum choice',r['comparison_tags']['fort_4']:'All-in castle 4'}
    rel=lambda path:os.path.relpath(path,report.parent)
    lines=['**Game 2 final challenge and selection**','',f"My Game 2 recommendation is **{tuple(allocation)}**. This is the allocation selected by the rule frozen before the final challenge. It also has the highest equal-block average among the {len(candidates)} frozen candidates. The comparison does not establish that its exact troop counts are uniquely optimal.",'',f"Game 1 remains **{tuple(cfg['game1_recommendation'])}**. Both vectors now have versioned recommendations. No application has been submitted.",'','**The result**','',f"The final challenge screened {a['development_field']:,} allocations using known development evidence, then froze {len(candidates)} candidates before new training or evaluation. Eight new arenas ran {a['arena_steps_replayed']:,} training steps in total. The evaluation contains {a['evaluation_conditional_cells']} conditional/snapshot cells and {a['iid_model_comparisons']} primary iid population comparisons, built from {a['legal_evaluation_triplets_regenerated']:,} shared opponent triples. Every frozen candidate faced exactly the same triples within a cell.",'','| Comparison | Allocation | Broad populations | Pressure populations | Adapting arenas | Equal-block mean | Rank by declared rule |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
    for cid in comparison:lines.append(f"| {label[cid]} | {tuple(candidates[cid]['allocation'])} | {' | '.join(f(p['block_scores'][cid][g])for g in ['core','pressure','arenas'])} | {f(p['equal_block_mean'][cid])} | {p['ranking'].index(cid)+1} |")
    lines+=['','These are model-conditional ranking payouts on the 0-to-9 scale. They are not predicted competition scores or applicant-frequency estimates. The last column ranks by the predeclared largest-block-regret rule, so it need not match the equal-block mean order. In particular, all-in five earns a higher equal-block mean than some strategies ranked above it because its weakest relative block performance is worse.','',f"![Frozen block comparison]({rel(study/'final-block-comparison.png')})",'','**Why this is the recommendation**','','Before new challenge samples, we fixed three coverage blocks: broad populations, pressure populations, and adapting arenas. Within each block, the benchmark is the best average score found in the frozen field. The rule chooses the candidate whose largest shortfall from those three benchmarks is smallest. Exact ties favor the higher equal-block mean, then the lexicographically smaller vector. This gives each block equal priority as a coverage category; it does not assert that each represents one third of applicants.','',f"For {tuple(allocation)}, the largest empirical block shortfall is {f(p['maximum_block_regret'][sel])} points. Its equal-block average is {f(p['equal_block_mean'][sel])}. The same vector wins the separate equal-block-mean comparison, so this selection is not dependent on choosing only the regret criterion.",'',f"The nearest regret competitor is {tuple(candidates[near]['allocation'])}, with largest shortfall {f(p['maximum_block_regret'][near])}. The difference is only {float(rational(p['maximum_block_regret'][near])-rational(p['maximum_block_regret'][sel])):.3f} points. We should treat those exact rankings as statistically close, not evidence of a special uniquely optimal number at each castle.",'',f"If the priority were the lowest score across the {a['iid_model_comparisons']} primary models, the alternative would be **{tuple(candidates[alt]['allocation'])}**. Its lowest score is {f(p['lowest_model_score'][alt])}, versus {f(p['lowest_model_score'][sel])} for the recommendation. Its equal-block mean is {f(p['equal_block_mean'][alt])}, versus {f(p['equal_block_mean'][sel])}. The alternative protects the weakest tested case better; the recommendation follows the coverage rule chosen beforehand. These minima exclude the separate concentrated-population diagnostics described below.",'','**How to read the allocation**','',f"The recommendation places {sum(allocation[:3])} troops in castles 1, 2, and 3, worth six castle points together. It retains {allocation[3]} at castle 4 and {allocation[4]} at castle 5. Its pattern contests smaller castles while other entries commit heavily to the expensive ones, and preserves chances to collect points that focused opponents leave cheaply available. This is an interpretation of its performance, not a proof that each troop has a globally optimal marginal value.",'','The four-player ranking objective makes those smaller castles useful: one extra castle point can change a finish and its prize. There is no eight-point threshold required to win a four-player group. The final models favor useful coverage across several castles over the previous narrow fortress choices. That does not imply that equal spreading or every broadly distributed allocation is good.','',f"Against the new learned arena distributions, the recommended fixed entry averages {f(p['block_scores'][sel]['arenas'])} ranking points. A player independently sampled from the same population as its three opponents averages 3.75 by symmetry. That reference calibrates the scoring; it is not a fixed-strategy guarantee. The recommended vector's lowest primary model is {f(p['lowest_model_score'][sel])}, so it does not beat that reference in every modeled population.",'','**What the final populations include**','','The broad block crosses four new styles with four residual mixtures. The styles use coalition priorities, rounded budgets, sparse allocations, and counter-aware threshold changes. Low, intermediate, and near-all-in fifth-bid profiles are mixed as balanced (one third each), low-heavy (65/25/10), intermediate-heavy (20/65/15), and near-heavy (20/20/60). Exact all-in-five prevalence is compared at 0%, 10%, 25%, and 50%, equally within this block. The residual laws include pure castle-4 entries and broad scout bids. The score calculation includes all group compositions, rather than linearly averaging scores against isolated families.','','The pressure block has twelve scenarios: four pressure families at 10%, 30%, or 60% person-level contamination of a broad background. These pressure families emphasize fourth-castle bids from 66 through 99, crowded pure castle-4 forts, cheap threshold overbids around known counters, and shifted near-all-in entries. The background includes 10% exact all-in-five entries. These levels are declared stress settings, not fitted human frequencies.','','The arena block averages eight new learning paths, giving each whole-run and last-100 population equal weight. Final snapshots are retained as diagnostics. The paths cross replicator versus prior-weighted score replacement, two explicit priors, and balanced versus heavy-five starts. All actions are retained; new current/history responses and large mutations can enter through step 300. The final 100 steps have no admissions, but learning and mutation continue. No post-freeze arena admission becomes a new recommendation candidate.','','The fifth-bid prior gives equal prior mass to exact all-in five, fifth bids 80-99, bids 0-3, and bids 4-79. The shape prior gives 20% to the five pure forts, 30% to other low-five entries, 30% to intermediate-five entries, and 20% to near-five entries. Both priors split an action\'s mass among any duplicate labels. These prevent an exact-label duplication artifact while retaining explicit assumptions about which families receive prior mass. Neither prior is a calibrated human model.','','**Arena percentages**','','These are last-100 average shares. Low-five includes pure castle 4, and the disjoint four columns sum to 100% before rounding. They describe simulated vectors, not applicant intentions.','','| Revision / prior / start | Exactly 100 in fifth | 80-99 in fifth | 0-3 in fifth | 4-79 in fifth |','| --- | ---: | ---: | ---: | ---: |']
    for name,path in r['paths'].items():
        shares=path['tail']['class_shares'];cells=[100*float(rational(shares[g]))for g in ['all_in_five','near_all_in_five','low_five','intermediate_five']];lines.append(f"| {path['rule']} / {path['prior']} / {path['initial']} | {' | '.join(f'{v:.2f}%'for v in cells)} |")
    lines+=['',f"The [full allocation percentages]({rel(study/'population-shares.csv')}) retain every final, whole-run, and tail population. Prior-weighted replacement changes the exact all-in-five share substantially when the prior changes; the replicator paths stay near 20% in these runs. This is further reason not to forecast applicants from one arena.",'','**The remaining counterexample**','',f"A legal population concentrated on **{tuple(counter['opponent'])}** gives the recommendation zero. Against three copies, our entry receives {group.castle_points[0]} castle points while each opponent receives {group.castle_points[1]}; it finishes fourth. This is an exact analytic counterexample, not sampling error. All {len(candidates)} frozen candidates received both the known pure-population stresses and an exact inverse-oracle check for their worst homogeneous opponent population.",'','These concentrated populations are diagnostic and do not enter the three-block recommendation rule. This distinction was declared before evaluation. The choice is based on performance across the stated coverage models, with its counters visible. It is not a distribution-free guarantee. The previous worst-group theorem still caps the strongest possible guarantee against arbitrary coordinated opponent triples at one payout point. We are not claiming that this recommended vector attains that bound.','','**Precision, validation, and stopping**','',f"The joint final sampling bounds allocate half the 5% error budget to cell scores and half to block means. The simultaneous cell-score bound is {r['cell_error_bound']:.4f} points. The block-mean bounds are {r['block_error_bounds']['core']:.4f} for broad populations, {r['block_error_bounds']['pressure']:.4f} for pressure populations, and {r['block_error_bounds']['arenas']:.4f} for arenas. These account for choosing among frozen candidates and extend to the convex copy curves. They do not quantify population-model error.",'',f"Under those conditional bounds, the selected candidate's true largest-block regret lies between {regret_intervals[sel]['lower']:.3f} and {regret_intervals[sel]['upper']:.3f}. Its excess regret above the best frozen candidate is bounded by {excess:.3f} points. This statement is restricted to the frozen field, block definitions, and generator laws, and is not a claim about a global game-theoretic optimum.",'',f"All 100 unit tests passed. The independent audit reproduced all {a['arena_steps_replayed']:,} arena steps and {a['independent_rank_gates']} independent gates, regenerated every challenge triple, and checked **{a['all_frozen_candidate_group_cells_foundation_checked']:,} candidate/group scores** directly with the foundation scorer. It independently reconstructed the selection, sensitivity alternatives, exact concentrated-population outcomes, hashes, and freeze chronology. Earlier checkpoints remain unchanged. The new arena response checks are finite-field witnesses; they do not establish Nash convergence.",'',f"The [audit record]({rel(study/'acceptance.json')}), [complete ranking]({rel(study/'candidate-ranking.csv')}), [copy curves]({rel(out/'copy-curves.csv')}), and [selected-vector text]({rel(out/'selected-game2.txt')}) preserve the evidence. We can now use the recommendation without running another open-ended search for a counter-free strategy. Further work would be a new version with a new freeze, not an unreported adjustment to this final test.",'','The public application was rechecked on October 30. Pittsburgh\'s regional is November 12, while its application deadline is **November 9 at 11:59 p.m. Eastern, or 10:59 p.m. Central**. The castle and ranking tie rules and 9/4/2/0 payouts still match this simulator. [Official application](https://pokerbot.sequoiacap.com/).','']
    text='\n'.join(lines);assert '\u2014'not in text and text.rstrip().endswith('.');report.write_text(text)
    save(out/'manifest.json',{'verifier_input_passed':True,'source_sha256':sha(Path(__file__)),'inputs':result['input_sha256'],'artifacts':{f.name:sha(f)for f in sorted(out.iterdir())if f.is_file()and f.name!='manifest.json'},'report_sha256':sha(report)})
    print('Verified final review and submission-vector text saved; no application submitted.')


if __name__=='__main__':main()
